  channel?: string | null;
  requester: string;
  title: string;
  at: number;
  thread: IntakeMessage[];
  tickets: TicketLink[];
  /** new, clarifying (asked the requester something), accepted (became or joined taskId) or declined. */
  status: string;
  taskId?: string | null;
  /** The goal id it looks like it belongs to. */
