/** Stop the auto-merge counting down on a task; a person merges it instead. */
export interface ClientMessage_TaskHoldMerge {
  type: "task.holdMerge";
  id: string;
}

export interface ClientMessage_TaskCancel {
  type: "task.cancel";
  id: string;
}

export interface ClientMessage_TaskRetry {
  type: "task.retry";
  id: string;
}

/** Reorder or schedule a task's place in the queue for sessions. A draft is sent to planning. */
export interface ClientMessage_TaskQueue {
  type: "task.queue";
  id: string;
  /** Move it ahead of this task; "top": the front of the queue. None moves it to the back, unless startAt or clearSchedule is given (they keep its place). */
  before?: string | null;
  /** Hold it until then (ms). */
  startAt?: number | null;
  /** Start it as soon as there's room. */
  clearSchedule?: boolean | null;
  /** Start its next session now, over the machine's slot count. */
  force?: boolean | null;
}

/** Reorder a draft among its goal's drafts; it stays a draft. */
export interface ClientMessage_TaskRankDraft {
  type: "task.rankDraft";
  id: string;
  /** Move it ahead of this draft; "top": the first draft. None moves it to the bottom. */
  before?: string | null;
}

